head.script:
// 테스트 설명, 유효성 값 설정
//  ★ _4 : mergeOptionStr = byrestricrow (윗쪽 Row 제약 가로 병합). description 은 _1 과 동일.
scwin.tData = {
    "description" : "[gridView > M > mergeCells]<br/>GridView 컴포넌트의 mergeCells 속성을 설정합니다.",
    "validation" : [
        "mergeOptionStr 'byrestricrow' 설정 시 윗쪽 Row 가 병합된 범위 내에서 'byrow' 병합합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// 검증 데이터 — mergeByRestricCol.xml 공식 샘플의 1~4행 데이터(10열 계층) 그대로 사용.
//  (왼쪽으로 갈수록 큰 그룹 → 오른쪽으로 갈수록 잘게 쪼개지는 가로 계층)
//    행0 : 10000 ×10                          (1x10 한 그룹)
//    행1 : 220000 ×5 / 320000 ×5              (경계 col5|col6)
//    행2 : 630000 ×4 / 730000 ×3 / 830000 ×3
//    행3 : 1240000 ×3 / 1340000 ×2 / 1440000 ×3 / 1540000 ×2
//   ── byrestricrow 제한 시연 ──
//    아래 행의 가로병합이 '윗 행이 병합된 범위' 를 넘지 못한다.
//    예) 행2 의 730000(원래 col5~col7) 은 윗 행(행1)의 경계 col5|col6 때문에 col5 단독 + col6~col7 로 잘려 병합된다.
scwin.makeData = function () {
    // mergeByRestricCol.xml 의 첫 루프(헤더 계층) = 10열 × 4행 = 40개 값
    let data1 = [];
    for (let f = 0; f < 10 * 4; f++) {
        let rx = Math.floor(f / 10) + 1;
        let zx = rx + 10 * Math.floor(f / (10 / rx));
        data1.push(zx * 10000);
    }
    return data1;
}



// comp 생성 : 10열 그리드를 동적 생성한다.
//  ★ mergeCells 속성은 생성 attribute 로 주지 않는다. (초기 미적용 상태로 생성 후 mergeCells() 메소드로 적용)
scwin.comp_init = async function () {
    // 기존 target / label / DataList 정리 (동일 id 재생성 무시 방지)
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove(dlt_bind.id);
    }
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="10열 계층 데이터(mergeByRestricCol 1~4행). byrestricrow=아래 행 가로병합이 윗 행 병합 범위를 넘지 못함(예: 행2 730000 이 col5 단독+col6~col7 로 잘림). par_mergeOptionStr 선택 후 mergeCells 버튼으로 적용"', '', 'label1');

    // 10열 DataList 인라인 생성 (공통 createDynamicDataList 는 col1~col4 만 정의하므로 직접 생성)
    let dlNS = $c.gcm.getNameSpace();
    let strDL = '';
    strDL += '<w2:dataList ' + dlNS + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDL += '<w2:columnInfo>';
    for (let i = 1; i <= 10; i++) {
        strDL += '<w2:column id="col' + i + '" name="col' + i + '" dataType="text"></w2:column>';
    }
    strDL += '</w2:columnInfo>';
    strDL += '<w2:data use="true"></w2:data>';
    strDL += '</w2:dataList>';
    $p.data.create(strDL);
    let arrDC = $p.data.getAllDataCollection("object");
    scwin["dlt_bind"] = arrDC[arrDC.length - 1];

    // 1~4행 계층 데이터 적재 (flat array → 10열씩 4행)
    dlt_bind.setData(scwin.makeData());

    // grid 생성 (mergeCells attribute 미부여 — mergeCells('byrestricrow') 메소드만으로 가로병합 적용)
    let properties = {
        dataList: "data:" + dlt_bind.id
    };
    let cList = $c.gcm.createCList(properties);

    let grp_comp = document.querySelector('.tc_group_basic');
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' checkAllType="false" defaultCellHeight="38" id="" style="width:680px;height:200px;">';
    strTarget += '<w2:caption style="" id="caption1" value="mergeCells byrestricrow sample (가로 계층 / 10열)"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    for (let i = 1; i <= 10; i++) {
        strTarget += '<w2:column width="65" style="" inputType="text" id="column' + i + '" value="col' + i + '"></w2:column>';
    }
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    for (let i = 1; i <= 10; i++) {
        strTarget += '<w2:column width="65" style="" inputType="text" id="col' + i + '" value=""></w2:column>';
    }
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);
}



// mergeCells 실행 : par_mergeOptionStr 값(필수)으로 target1.mergeCells(mergeOptionStr) 호출
//  · options(선택) 파라미터는 _5(options 전용) 샘플에서 다루므로 여기서는 생략한다.
scwin.btn_mergeCells_onclick = function (e) {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    let mode = par_mergeOptionStr.getValue();

    target1.mergeCells(mode);

    bottom.setReturnValue("[옵션] mergeCells=" + target1.options.mergeCells + " / mergeOptionStr='" + mode + "'");

    scwin.printMergeState(bottom);
}



// 병합 상태 확인 : 각 Body td 의 rowSpan/colSpan 을 읽어 세로(⬇)/가로(➡)/블록(⬛) 병합 그룹을 출력
//  - td 셀렉터는 gid = target1.id 사용(e.target.id 는 버튼 id 라 사용 불가)
//  - 흡수되어 표시되지 않는 td 와 중복 키(고정/스크롤 영역 중복 id)는 제외
scwin.printMergeState = function (bottom) {
    let gid = target1.id;
    let tds = document.querySelectorAll("td[id*='" + gid + "_cell_']");
    if (tds.length === 0) {
        bottom.setReturnValue("body cell td 를 찾을 수 없습니다.");
        return;
    }

    let rowSpanCnt = 0;
    let colSpanCnt = 0;
    let descs = [];
    let seen = {};

    for (let i = 0; i < tds.length; i++) {
        let td = tds[i];
        if (getComputedStyle(td).display === 'none' || td.offsetParent === null) continue;
        let rs = td.rowSpan || 1;
        let cs = td.colSpan || 1;
        let m = td.id.match(/_cell_(\d+)_(\d+)/);
        if (!m) continue;
        let r = Number(m[1]), c = Number(m[2]);

        let key = r + "_" + c;
        if (seen[key]) continue;
        seen[key] = true;

        if (rs > 1 || cs > 1) {
            if (rs > 1) rowSpanCnt++;
            if (cs > 1) colSpanCnt++;
            let val = (td.textContent || "").trim();
            if (rs > 1 && cs === 1) {
                descs.push("⬇ col" + (c + 1) + " [행" + r + "~행" + (r + rs - 1) + "] 세로병합 = '" + val + "'");
            } else if (cs > 1 && rs === 1) {
                descs.push("➡ 행" + r + " [col" + (c + 1) + "~col" + (c + cs) + "] 가로병합 = '" + val + "'");
            } else {
                descs.push("⬛ [행" + r + "~행" + (r + rs - 1) + ", col" + (c + 1) + "~col" + (c + cs) + "] 블록병합(" + rs + "x" + cs + ") = '" + val + "'");
            }
        }
    }

    let modeName;
    if (rowSpanCnt === 0 && colSpanCnt === 0) modeName = "병합 없음";
    else if (rowSpanCnt > 0 && colSpanCnt === 0) modeName = "세로(rowSpan) 병합";
    else if (colSpanCnt > 0 && rowSpanCnt === 0) modeName = "가로(colSpan) 병합";
    else modeName = "혼합(블록) 병합";

    bottom.setReturnValue("판정 : " + modeName + " / 병합 그룹 " + descs.length + "개");
    if (descs.length === 0) {
        bottom.setReturnValue("병합된 셀 없음");
    } else {
        for (let d = 0; d < descs.length; d++) bottom.setReturnValue(descs[d]);
    }
}
